using System.Text.Json;
using Core.Services;
using Core.Transactions;
using Modules.Tax.DTOs;
using Modules.Tax.Entities;
using Npgsql;
using Shared.Primitives.Identifiers;

namespace Modules.Tax.Repositories;

public sealed class TaxRegistrationRepository(NpgsqlDataSource dataSource, ITransactionCoordinator transactions, ILegalEntityFinancialReadStore legalEntities)
{
    public async Task<TaxRegistrationDto> CreateAsync(Guid tenantId, Guid actorId, Guid correlationId, TaxRegistrationRequest request, CancellationToken cancellationToken)
    {
        Validate(request.CountryCode, request.SchemeCode, request.RegistrationNumber, request.Status, request.EffectiveFrom);
        if(request.Status==TaxRegistrationStatus.Deregistered.ToString())throw new TaxException("tax.registration_status_invalid","Create a registration first, then record deregistration with an effective date.");
        if (await legalEntities.GetTimeZoneAsync(new(tenantId), new(request.LegalEntityId), cancellationToken) is null) throw new TaxException("tax.legal_entity_not_found", "The Legal Entity was not found in this tenant.");
        var id = Guid.CreateVersion7(); var memberId = Guid.CreateVersion7();
        return await transactions.ExecuteAsync<TaxRegistrationDto>(new(tenantId), async (context, token) =>
        {
            await using (var insert = new NpgsqlCommand("insert into foundation_tax.tax_registration(tenant_id,id,registration_series_id,country_code,scheme_code,registration_number,status,effective_from,authority,evidence_reference,version,created_at,updated_at) values($1,$2,$2,$3,$4,$5,$6,$7,$8,$9,1,now(),now())", context.Connection, context.Transaction))
            {
                insert.Parameters.AddWithValue(tenantId); insert.Parameters.AddWithValue(id); insert.Parameters.AddWithValue(request.CountryCode); insert.Parameters.AddWithValue(request.SchemeCode); insert.Parameters.AddWithValue((object?)request.RegistrationNumber ?? DBNull.Value); insert.Parameters.AddWithValue(request.Status); insert.Parameters.AddWithValue(request.EffectiveFrom); insert.Parameters.AddWithValue((object?)request.Authority ?? DBNull.Value); insert.Parameters.AddWithValue((object?)request.EvidenceReference ?? DBNull.Value); await insert.ExecuteNonQueryAsync(token);
            }
            await using (var member = new NpgsqlCommand("insert into foundation_tax.tax_registration_member(tenant_id,id,registration_id,legal_entity_id,effective_from,membership_status) values($1,$2,$3,$4,$5,'Active')", context.Connection, context.Transaction))
            { member.Parameters.AddWithValue(tenantId); member.Parameters.AddWithValue(memberId); member.Parameters.AddWithValue(id); member.Parameters.AddWithValue(request.LegalEntityId); member.Parameters.AddWithValue(request.EffectiveFrom); await member.ExecuteNonQueryAsync(token); }
            var result = new TaxRegistrationDto(id,id,null,request.CountryCode,request.SchemeCode,request.RegistrationNumber,request.Status,request.EffectiveFrom,null,request.Authority,request.EvidenceReference,1);
            await AuditAsync(context, tenantId, actorId, request.LegalEntityId, correlationId, "RegistrationCreated", id, null, result, token);
            context.AddOutbox(new(Guid.CreateVersion7(),"TaxRegistrationChangedV1",JsonSerializer.Serialize(new { id, request.LegalEntityId, request.CountryCode, request.SchemeCode, request.Status, request.EffectiveFrom }),new(tenantId),DateTimeOffset.UtcNow,correlationId,id,"tax"));
            return result;
        }, cancellationToken);
    }

    public async Task<TaxRegistrationDto> ChangeAsync(Guid tenantId, Guid actorId, Guid correlationId, Guid id, Guid legalEntityId, TaxRegistrationChangeRequest request, bool deregister, CancellationToken cancellationToken)
    {
        if (!Enum.TryParse<TaxRegistrationStatus>(request.Status, true, out var status)) throw new TaxException("tax.registration_status_invalid", "Registration status is not supported.");
        if (deregister) status = TaxRegistrationStatus.Deregistered;
        if (status == TaxRegistrationStatus.Registered && string.IsNullOrWhiteSpace(request.RegistrationNumber)) throw new TaxException("tax.registration_number_required", "A registered Tax Registration requires a registration number.");
        return await transactions.ExecuteAsync<TaxRegistrationDto>(new(tenantId), async (context, token) =>
        {
            await using var currentCommand = new NpgsqlCommand("select registration_series_id,country_code,scheme_code,registration_number,status,effective_from,effective_to,authority,evidence_reference,version from foundation_tax.tax_registration r where tenant_id=$1 and id=$2 and effective_from<=$4 and (effective_to is null or effective_to > $4) and exists(select 1 from foundation_tax.tax_registration_member m where m.tenant_id=r.tenant_id and m.registration_id=r.id and m.legal_entity_id=$3 and m.membership_status='Active' and m.effective_from <= $4 and (m.effective_to is null or m.effective_to > $4)) for update", context.Connection, context.Transaction);
            currentCommand.Parameters.AddWithValue(tenantId); currentCommand.Parameters.AddWithValue(id); currentCommand.Parameters.AddWithValue(legalEntityId); currentCommand.Parameters.AddWithValue(request.EffectiveFrom);
            await using var reader = await currentCommand.ExecuteReaderAsync(token); if (!await reader.ReadAsync(token)) throw new TaxException("tax.registration_not_found", "The Tax Registration is not active for this Legal Entity.");
            var series = reader.GetGuid(0); var country = reader.GetString(1); var scheme = reader.GetString(2); var oldNumber = reader.IsDBNull(3)?null:reader.GetString(3); var oldStatus=reader.GetString(4); var oldFrom=reader.GetFieldValue<DateOnly>(5); var oldTo=reader.IsDBNull(6)?(DateOnly?)null:reader.GetFieldValue<DateOnly>(6); var oldAuthority=reader.IsDBNull(7)?null:reader.GetString(7); var oldEvidence=reader.IsDBNull(8)?null:reader.GetString(8); var oldVersion=reader.GetInt64(9); await reader.CloseAsync();
            TaxRegistrationLifecycle.ValidateTransition(Enum.Parse<TaxRegistrationStatus>(oldStatus),status);
            if (request.EffectiveFrom <= oldFrom || oldTo is { } end && request.EffectiveFrom >= end) throw new TaxException("tax.registration_effective_date_invalid", "A registration change must fall after the version start and within its open effective period.");
            Validate(country, scheme, request.RegistrationNumber ?? oldNumber, status.ToString(), request.EffectiveFrom);
            await using (var close = new NpgsqlCommand("update foundation_tax.tax_registration set effective_to=$3,updated_at=now() where tenant_id=$1 and id=$2", context.Connection, context.Transaction)) { close.Parameters.AddWithValue(tenantId); close.Parameters.AddWithValue(id); close.Parameters.AddWithValue(request.EffectiveFrom); await close.ExecuteNonQueryAsync(token); }
            var nextId=Guid.CreateVersion7();
            await using (var insert = new NpgsqlCommand("insert into foundation_tax.tax_registration(tenant_id,id,registration_series_id,supersedes_id,country_code,scheme_code,registration_number,status,effective_from,effective_to,authority,evidence_reference,version,created_at,updated_at) values($1,$2,$3,$4,$5,$6,$7,$8,$9,null,$10,$11,$12,now(),now())", context.Connection, context.Transaction))
            { insert.Parameters.AddWithValue(tenantId); insert.Parameters.AddWithValue(nextId); insert.Parameters.AddWithValue(series); insert.Parameters.AddWithValue(id); insert.Parameters.AddWithValue(country); insert.Parameters.AddWithValue(scheme); insert.Parameters.AddWithValue((object?)request.RegistrationNumber ?? oldNumber ?? (object)DBNull.Value); insert.Parameters.AddWithValue(status.ToString()); insert.Parameters.AddWithValue(request.EffectiveFrom); insert.Parameters.AddWithValue(request.Authority ?? oldAuthority ?? (object)DBNull.Value); insert.Parameters.AddWithValue(request.EvidenceReference ?? oldEvidence ?? (object)DBNull.Value); insert.Parameters.AddWithValue(oldVersion+1); await insert.ExecuteNonQueryAsync(token); }
            if (status != TaxRegistrationStatus.Deregistered)
                await using (var copyMembers = new NpgsqlCommand("insert into foundation_tax.tax_registration_member(tenant_id,id,registration_id,legal_entity_id,effective_from,effective_to,membership_status) select tenant_id,gen_random_uuid(),$3,legal_entity_id,greatest(effective_from,$4),effective_to,'Active' from foundation_tax.tax_registration_member where tenant_id=$1 and registration_id=$2 and membership_status='Active' and (effective_to is null or effective_to > $4)", context.Connection, context.Transaction)) { copyMembers.Parameters.AddWithValue(tenantId); copyMembers.Parameters.AddWithValue(id); copyMembers.Parameters.AddWithValue(nextId); copyMembers.Parameters.AddWithValue(request.EffectiveFrom); await copyMembers.ExecuteNonQueryAsync(token); }
            await using (var endMembers = new NpgsqlCommand("update foundation_tax.tax_registration_member set effective_to=$3,membership_status=case when $4='Deregistered' then 'Ended' else membership_status end where tenant_id=$1 and registration_id=$2 and effective_from<$3 and (effective_to is null or effective_to>$3)", context.Connection, context.Transaction)) { endMembers.Parameters.AddWithValue(tenantId); endMembers.Parameters.AddWithValue(id); endMembers.Parameters.AddWithValue(request.EffectiveFrom); endMembers.Parameters.AddWithValue(status.ToString()); await endMembers.ExecuteNonQueryAsync(token); }
            var result=new TaxRegistrationDto(nextId,series,id,country,scheme,request.RegistrationNumber??oldNumber,status.ToString(),request.EffectiveFrom,null,request.Authority??oldAuthority,request.EvidenceReference??oldEvidence,oldVersion+1);
            await AuditAsync(context,tenantId,actorId,legalEntityId,correlationId,deregister?"RegistrationDeregistered":"RegistrationChanged",nextId,new { id, oldStatus, oldFrom, oldTo },result,token);
            context.AddOutbox(new(Guid.CreateVersion7(),"TaxRegistrationChangedV1",JsonSerializer.Serialize(new { id=nextId, supersedesId=id, legalEntityId, status=result.Status, effectiveFrom=result.EffectiveFrom }),new(tenantId),DateTimeOffset.UtcNow,correlationId,nextId,"tax")); return result;
        }, cancellationToken);
    }

    public async Task<IReadOnlyList<TaxRegistrationDto>> ListAsync(Guid tenantId, Guid legalEntityId, string? schemeCode, CancellationToken cancellationToken) => await QueryAsync(tenantId,"where exists(select 1 from foundation_tax.tax_registration_member m where m.tenant_id=r.tenant_id and m.registration_id=r.id and m.legal_entity_id=$2) and ($3::text is null or r.scheme_code=$3)",cancellationToken,legalEntityId,(object?)schemeCode??DBNull.Value);
    public async Task<IReadOnlyList<TaxRegistrationDto>> HistoryAsync(Guid tenantId, Guid id, Guid legalEntityId, CancellationToken cancellationToken)
    {
        await using var connection=await dataSource.OpenConnectionAsync(cancellationToken); await using var tx=await connection.BeginTransactionAsync(cancellationToken); await SetTenantAsync(connection,tx,tenantId,cancellationToken);
        await using var command=new NpgsqlCommand("select registration_series_id from foundation_tax.tax_registration r where tenant_id=$1 and id=$2 and exists(select 1 from foundation_tax.tax_registration_member m where m.tenant_id=r.tenant_id and m.registration_id=r.id and m.legal_entity_id=$3)",connection,tx); command.Parameters.AddWithValue(tenantId); command.Parameters.AddWithValue(id); command.Parameters.AddWithValue(legalEntityId); var value=await command.ExecuteScalarAsync(cancellationToken);
        return value is not Guid series?[]:await QueryAsync(tenantId,"where r.registration_series_id=$2",cancellationToken,series);
    }
    public async Task<TaxRegistrationDto?> GetAsync(Guid tenantId, Guid id, Guid legalEntityId, CancellationToken cancellationToken)
    { var values=await QueryAsync(tenantId,"where r.id=$2 and exists(select 1 from foundation_tax.tax_registration_member m where m.tenant_id=r.tenant_id and m.registration_id=r.id and m.legal_entity_id=$3)",cancellationToken,id,legalEntityId); return values.Count==0?null:values[0]; }

    public async Task<TaxRegistrationMemberDto> AddMemberAsync(Guid tenant,Guid actor,Guid correlation,Guid registrationId,TaxRegistrationMemberRequest request,CancellationToken ct)
    {
        if(await legalEntities.GetTimeZoneAsync(new(tenant),new(request.LegalEntityId),ct)is null)throw new TaxException("tax.legal_entity_not_found","The Legal Entity was not found in this tenant.");var id=Guid.CreateVersion7();
        return await transactions.ExecuteAsync<TaxRegistrationMemberDto>(new(tenant),async(context,token)=>
        {
            var valid=await ExistsAsync(context,"select exists(select 1 from foundation_tax.tax_registration where tenant_id=$1 and id=$2 and status<>'Deregistered' and effective_from<=$3 and (effective_to is null or effective_to>$3))",token,tenant,registrationId,request.EffectiveFrom);if(!valid)throw new TaxException("tax.registration_not_available","Registration is not active at this membership start date.");
            var overlap=await ExistsAsync(context,"select exists(select 1 from foundation_tax.tax_registration_member where tenant_id=$1 and registration_id=$2 and legal_entity_id=$3 and daterange(effective_from,effective_to,'[)') && daterange($4,null,'[)'))",token,tenant,registrationId,request.LegalEntityId,request.EffectiveFrom);if(overlap)throw new TaxException("tax.membership_overlap","This Legal Entity already has an overlapping membership for the Registration.");
            await using var insert=new NpgsqlCommand("insert into foundation_tax.tax_registration_member(tenant_id,id,registration_id,legal_entity_id,effective_from,membership_status) values($1,$2,$3,$4,$5,'Active')",context.Connection,context.Transaction);insert.Parameters.AddWithValue(tenant);insert.Parameters.AddWithValue(id);insert.Parameters.AddWithValue(registrationId);insert.Parameters.AddWithValue(request.LegalEntityId);insert.Parameters.AddWithValue(request.EffectiveFrom);await insert.ExecuteNonQueryAsync(token);
            var result=new TaxRegistrationMemberDto(id,registrationId,request.LegalEntityId,request.EffectiveFrom,null,"Active");await AuditAsync(context,tenant,actor,request.LegalEntityId,correlation,"RegistrationMembershipChanged",id,null,result,token);context.AddOutbox(new(Guid.CreateVersion7(),"TaxRegistrationChangedV1",JsonSerializer.Serialize(new{registrationId,memberId=id,request.LegalEntityId,request.EffectiveFrom}),new(tenant),DateTimeOffset.UtcNow,correlation,id,"tax"));return result;
        },ct);
    }

    public async Task<IReadOnlyList<TaxRegistrationMemberDto>> ListMembersAsync(Guid tenant,Guid registrationId,DateOnly? at,CancellationToken ct)
    {
        await using var c=await dataSource.OpenConnectionAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await SetTenantAsync(c,tx,tenant,ct);await using var cmd=new NpgsqlCommand("select id,registration_id,legal_entity_id,effective_from,effective_to,membership_status from foundation_tax.tax_registration_member where tenant_id=$1 and registration_id=$2 and ($3::date is null or(effective_from<=$3 and(effective_to is null or effective_to>$3))) order by effective_from desc",c,tx);cmd.Parameters.AddWithValue(tenant);cmd.Parameters.AddWithValue(registrationId);cmd.Parameters.AddWithValue((object?)at??DBNull.Value);await using var reader=await cmd.ExecuteReaderAsync(ct);var result=new List<TaxRegistrationMemberDto>();while(await reader.ReadAsync(ct))result.Add(new(reader.GetGuid(0),reader.GetGuid(1),reader.GetGuid(2),reader.GetFieldValue<DateOnly>(3),reader.IsDBNull(4)?null:reader.GetFieldValue<DateOnly>(4),reader.GetString(5)));return result;
    }

    public async Task<TaxRegistrationMemberDto> EndMemberAsync(Guid tenant,Guid actor,Guid correlation,Guid memberId,Guid legalEntityId,DateOnly effectiveTo,CancellationToken ct)
    {
        var registrationId=await transactions.ExecuteAsync<Guid>(new(tenant),async(context,token)=>{await using var cmd=new NpgsqlCommand("update foundation_tax.tax_registration_member set effective_to=$4,membership_status='Ended' where tenant_id=$1 and id=$2 and legal_entity_id=$3 and effective_to is null and effective_from<$4 returning registration_id",context.Connection,context.Transaction);cmd.Parameters.AddWithValue(tenant);cmd.Parameters.AddWithValue(memberId);cmd.Parameters.AddWithValue(legalEntityId);cmd.Parameters.AddWithValue(effectiveTo);var registration=await cmd.ExecuteScalarAsync(token);if(registration is null)throw new TaxException("tax.membership_not_endable","Registration membership was not found or effective end date is invalid.");var registrationId=(Guid)registration;await AuditAsync(context,tenant,actor,legalEntityId,correlation,"RegistrationMembershipEnded",memberId,null,new{effectiveTo},token);context.AddOutbox(new(Guid.CreateVersion7(),"TaxRegistrationChangedV1",JsonSerializer.Serialize(new{registrationId,memberId,legalEntityId,effectiveTo}),new(tenant),DateTimeOffset.UtcNow,correlation,memberId,"tax"));return registrationId;},ct);
        var result=await ListMembersAsync(tenant,registrationId,null,ct);foreach(var member in result)if(member.Id==memberId)return member;throw new TaxException("tax.membership_not_found","Registration membership was not found.");
    }

    private async Task<IReadOnlyList<TaxRegistrationDto>> QueryAsync(Guid tenantId,string filter,CancellationToken token,params object[] args)
    {
        await using var connection=await dataSource.OpenConnectionAsync(token); await using var tx=await connection.BeginTransactionAsync(token); await SetTenantAsync(connection,tx,tenantId,token);
        await using var command=new NpgsqlCommand("select r.id,r.registration_series_id,r.supersedes_id,r.country_code,r.scheme_code,r.registration_number,r.status,r.effective_from,r.effective_to,r.authority,r.evidence_reference,r.version from foundation_tax.tax_registration r "+filter+" order by r.registration_series_id,r.effective_from desc limit 500",connection,tx); command.Parameters.AddWithValue(tenantId); for(var i=0;i<args.Length;i++)command.Parameters.AddWithValue(args[i]??DBNull.Value);
        await using var reader=await command.ExecuteReaderAsync(token); var rows=new List<TaxRegistrationDto>(); while(await reader.ReadAsync(token))rows.Add(new(reader.GetGuid(0),reader.GetGuid(1),reader.IsDBNull(2)?null:reader.GetGuid(2),reader.GetString(3),reader.GetString(4),reader.IsDBNull(5)?null:reader.GetString(5),reader.GetString(6),reader.GetFieldValue<DateOnly>(7),reader.IsDBNull(8)?null:reader.GetFieldValue<DateOnly>(8),reader.IsDBNull(9)?null:reader.GetString(9),reader.IsDBNull(10)?null:reader.GetString(10),reader.GetInt64(11))); return rows;
    }
    private static void Validate(string country,string scheme,string? number,string status,DateOnly from)
    {if(country.Length!=2||country.Any(c=>!char.IsAsciiLetterUpper(c))||string.IsNullOrWhiteSpace(scheme)||scheme.Length>40||scheme.Any(c=>!char.IsAsciiLetterUpper(c)&&!char.IsAsciiDigit(c)&&c!='_'))throw new TaxException("tax.registration_reference_invalid","Country and stable Tax Scheme codes are required.");if(!Enum.TryParse<TaxRegistrationStatus>(status,true,out var parsed))throw new TaxException("tax.registration_status_invalid","Registration status is not supported.");if(parsed==TaxRegistrationStatus.Registered&&string.IsNullOrWhiteSpace(number))throw new TaxException("tax.registration_number_required","Registered status requires a registration number.");if(from==default)throw new TaxException("tax.registration_effective_date_invalid","An effective date is required.");}
    private static async Task AuditAsync(ITransactionContext context,Guid tenant,Guid actor,Guid entity,Guid correlation,string action,Guid id,object? before,object? after,CancellationToken token)
    {await using var cmd=new NpgsqlCommand("insert into foundation_tax.tax_audit(tenant_id,id,legal_entity_id,actor_id,operation,entity_type,entity_id,before_state,after_state,occurred_at,correlation_id) values($1,$2,$3,$4,$5,'TaxRegistration',$6,$7::jsonb,$8::jsonb,now(),$9)",context.Connection,context.Transaction);cmd.Parameters.AddWithValue(tenant);cmd.Parameters.AddWithValue(Guid.CreateVersion7());cmd.Parameters.AddWithValue(entity);cmd.Parameters.AddWithValue(actor);cmd.Parameters.AddWithValue(action);cmd.Parameters.AddWithValue(id);cmd.Parameters.AddWithValue(before is null?DBNull.Value:JsonSerializer.Serialize(before));cmd.Parameters.AddWithValue(after is null?DBNull.Value:JsonSerializer.Serialize(after));cmd.Parameters.AddWithValue(correlation);await cmd.ExecuteNonQueryAsync(token);}
    private static async Task SetTenantAsync(NpgsqlConnection c,NpgsqlTransaction tx,Guid tenant,CancellationToken token){await using var cmd=new NpgsqlCommand("select set_config('app.tenant_id',$1,true)",c,tx);cmd.Parameters.AddWithValue(tenant.ToString("D"));await cmd.ExecuteNonQueryAsync(token);}
    private static async Task<bool> ExistsAsync(ITransactionContext context,string sql,CancellationToken token,params object[] values){await using var cmd=new NpgsqlCommand(sql,context.Connection,context.Transaction);foreach(var value in values)cmd.Parameters.AddWithValue(value??DBNull.Value);return (bool)(await cmd.ExecuteScalarAsync(token)??false);}
}
